const {
  withAndroidManifest,
  withStringsXml,
  withDangerousMod,
  AndroidConfig,
} = require('@expo/config-plugins');
const fs = require('fs');
const path = require('path');

const { getMainApplicationOrThrow } = AndroidConfig.Manifest;

const SERVICE_NAME = 'PaymentAccessibilityService';
const TEMPLATES_DIR = path.join(__dirname, 'templates');

/**
 * Registers an Android AccessibilityService that reads the GPay "Enter your
 * PIN" screen and forwards it to the app via the expensetracker://add deep link.
 *
 * Native folders (/android) are gitignored and regenerated by `expo prebuild`,
 * so this plugin re-creates the service files and manifest/string entries from
 * committed templates on every build.
 */
function withPaymentAccessibilityService(config) {
  const packageName = config.android?.package;

  config = withStringsXml(config, (config) => {
    config.modResults = AndroidConfig.Strings.setStringItem(
      [
        { $: { name: 'accessibility_service_label' }, _: 'expense-tracker payment reader' },
        {
          $: { name: 'accessibility_service_description' },
          _: 'Reads your GPay payment confirmation screen to automatically log expenses. Nothing leaves your device.',
        },
      ],
      config.modResults
    );
    return config;
  });

  config = withAndroidManifest(config, (config) => {
    const app = getMainApplicationOrThrow(config.modResults);
    if (!app.service) app.service = [];
    app.service.push({
      $: {
        'android:name': `.${SERVICE_NAME}`,
        'android:exported': 'false',
        'android:label': '@string/accessibility_service_label',
        'android:permission': 'android.permission.BIND_ACCESSIBILITY_SERVICE',
      },
      'intent-filter': [
        {
          action: [{ $: { 'android:name': 'android.accessibilityservice.AccessibilityService' } }],
        },
      ],
      'meta-data': [
        {
          $: {
            'android:name': 'android.accessibilityservice',
            'android:resource': '@xml/accessibility_service_config',
          },
        },
      ],
    });

    // Debug-only trigger so the capture flow can be exercised without a real
    // payment: adb shell am broadcast -a com.buildqwertyduh.expensetracker.DEBUG_CAPTURE --es text "..."
    // DebugCaptureReceiver ignores the broadcast unless BuildConfig.DEBUG.
    if (!app.receiver) app.receiver = [];
    app.receiver.push({
      $: {
        'android:name': '.DebugCaptureReceiver',
        'android:exported': 'true',
      },
      'intent-filter': [
        {
          action: [
            { $: { 'android:name': 'com.buildqwertyduh.expensetracker.DEBUG_CAPTURE' } },
          ],
        },
      ],
    });
    return config;
  });

  config = withDangerousMod(config, [
    'android',
    (config) => {
      const projectRoot = config.modRequest.platformProjectRoot;
      const javaDir = path.join(
        projectRoot,
        'app',
        'src',
        'main',
        'java',
        ...packageName.split('.')
      );
      const xmlDir = path.join(projectRoot, 'app', 'src', 'main', 'res', 'xml');

      fs.mkdirSync(javaDir, { recursive: true });
      fs.mkdirSync(xmlDir, { recursive: true });

      // Copy every Kotlin template into the app package, rewriting the package
      // declaration so templates stay package-agnostic in the repo.
      const kotlinFiles = fs
        .readdirSync(TEMPLATES_DIR)
        .filter((file) => file.endsWith('.kt'));
      for (const file of kotlinFiles) {
        const source = fs.readFileSync(path.join(TEMPLATES_DIR, file), 'utf8');
        const kotlin = source.replace(/^package .*$/m, `package ${packageName}`);
        fs.writeFileSync(path.join(javaDir, file), kotlin);
      }

      const xmlTemplate = fs.readFileSync(
        path.join(TEMPLATES_DIR, 'accessibility_service_config.xml'),
        'utf8'
      );
      fs.writeFileSync(path.join(xmlDir, 'accessibility_service_config.xml'), xmlTemplate);

      return config;
    },
  ]);

  return config;
}

module.exports = withPaymentAccessibilityService;
